//! Schema statements (`CREATE`/`DROP TABLE`, indexes, `ALTER TABLE`) for
//! the Oracle backend, and the statements that run them on an
//! [`Executor`].
//!
//! Auto-increment columns are identity columns (`GENERATED BY DEFAULT ON
//! NULL AS IDENTITY`). `IF [NOT] EXISTS` is a PL/SQL block that ignores
//! the one error the statement would raise when the object exists (or
//! doesn't), so it works before 23ai too. Oracle commits around every DDL
//! statement, so none of this can be rolled back.

use std::fmt::Write as _;

use crate::schema::{AlterOperation, DataType};
use crate::{DatabaseError, DatabaseValue};

use super::Executor;

/// `ORA-00955: name is already used by an existing object`.
const ALREADY_EXISTS: i32 = 955;
/// `ORA-00942: table or view does not exist`.
const NO_SUCH_TABLE: i32 = 942;
/// `ORA-01418: specified index does not exist`.
const NO_SUCH_INDEX: i32 = 1418;

fn identifier(name: &str) -> String {
    crate::query::render_identifier(name, '"')
}

/// `name` in double quotes, for names read back from the catalog.
#[cfg(feature = "cascade")]
fn quoted(name: &str) -> String {
    format!("\"{}\"", name.replace('"', "\"\""))
}

/// `text` as a `'...'` literal.
fn literal(text: &str) -> String {
    format!("'{}'", text.replace('\'', "''"))
}

/// `sql` run in a PL/SQL block that ignores `ORA-<code>`.
fn ignoring(sql: &str, code: i32) -> String {
    format!(
        "BEGIN EXECUTE IMMEDIATE {}; EXCEPTION WHEN OTHERS THEN IF SQLCODE <> -{code} THEN \
         RAISE; END IF; END;",
        literal(sql)
    )
}

/// The Oracle type a [`DataType`] is stored as.
fn type_sql(data_type: &DataType) -> Result<String, DatabaseError> {
    Ok(match data_type {
        DataType::VarChar(size) => format!("VARCHAR2({size} CHAR)"),
        DataType::Char(size) => format!("CHAR({size} CHAR)"),
        DataType::Text | DataType::Json | DataType::Jsonb => "CLOB".to_string(),
        DataType::TinyInt | DataType::SmallInt => "NUMBER(5)".to_string(),
        DataType::Int | DataType::Serial => "NUMBER(10)".to_string(),
        DataType::BigInt | DataType::BigSerial => "NUMBER(19)".to_string(),
        DataType::Real => "BINARY_FLOAT".to_string(),
        DataType::Double => "BINARY_DOUBLE".to_string(),
        DataType::Decimal(precision, scale) => format!("NUMBER({precision}, {scale})"),
        DataType::Money => "NUMBER(19, 4)".to_string(),
        // `BOOLEAN` exists in SQL from 23ai only; 1/0 works everywhere.
        DataType::Bool => "NUMBER(1)".to_string(),
        DataType::Date => "DATE".to_string(),
        // Oracle has no time-of-day type; times are bound as text.
        DataType::Time => "VARCHAR2(18)".to_string(),
        DataType::DateTime => "TIMESTAMP".to_string(),
        DataType::Timestamp => "TIMESTAMP WITH TIME ZONE".to_string(),
        DataType::Binary(Some(size)) if *size <= 2000 => format!("RAW({size})"),
        DataType::Blob | DataType::Binary(_) => "BLOB".to_string(),
        DataType::Uuid => "VARCHAR2(36)".to_string(),
        DataType::Xml => "XMLTYPE".to_string(),
        DataType::Inet => "VARCHAR2(45)".to_string(),
        DataType::MacAddr => "VARCHAR2(17)".to_string(),
        DataType::Array(_) => {
            return Err(DatabaseError::UnsupportedDataType(
                "arrays (Oracle has no array column type)".to_string(),
            ));
        }
        DataType::Custom(name) => name.clone(),
    })
}

/// A column default as an Oracle literal or expression.
fn default_sql(value: &DatabaseValue) -> String {
    use DatabaseValue as V;
    if crate::query::Expression::is_null(value) {
        return "NULL".to_string();
    }
    if let Some(now) = super::value::now_sql(value) {
        return now;
    }
    match value {
        V::String(text) | V::StringOpt(Some(text)) => literal(text),
        V::Bool(value) | V::BoolOpt(Some(value)) => if *value { "1" } else { "0" }.to_string(),
        V::Int8(value) | V::Int8Opt(Some(value)) => value.to_string(),
        V::Int16(value) | V::Int16Opt(Some(value)) => value.to_string(),
        V::Int32(value) | V::Int32Opt(Some(value)) => value.to_string(),
        V::Int64(value) | V::Int64Opt(Some(value)) => value.to_string(),
        V::UInt8(value) | V::UInt8Opt(Some(value)) => value.to_string(),
        V::UInt16(value) | V::UInt16Opt(Some(value)) => value.to_string(),
        V::UInt32(value) | V::UInt32Opt(Some(value)) => value.to_string(),
        V::UInt64(value) | V::UInt64Opt(Some(value)) => value.to_string(),
        V::Real32(value) | V::Real32Opt(Some(value)) => value.to_string(),
        V::Real64(value) | V::Real64Opt(Some(value)) => value.to_string(),
        #[cfg(feature = "decimal")]
        V::Decimal(value) | V::DecimalOpt(Some(value)) => value.to_string(),
        #[cfg(feature = "uuid")]
        V::Uuid(value) | V::UuidOpt(Some(value)) => literal(&value.to_string()),
        V::DateTime(value) => format!(
            "TIMESTAMP {}",
            literal(&value.format("%Y-%m-%d %H:%M:%S%.f").to_string())
        ),
        V::Date(value) | V::DateOpt(Some(value)) => format!("DATE {}", literal(&value.to_string())),
        V::Time(value) | V::TimeOpt(Some(value)) => literal(&value.to_string()),
        V::DateTimeTz(value) | V::DateTimeTzOpt(Some(value)) => format!(
            "TIMESTAMP {}",
            literal(&value.format("%Y-%m-%d %H:%M:%S%.f %:z").to_string())
        ),
        V::Bytes(bytes) | V::BytesOpt(Some(bytes)) => {
            let mut hex = String::new();
            for byte in bytes {
                let _ = write!(hex, "{byte:02X}");
            }
            format!("HEXTORAW({})", literal(&hex))
        }
        #[cfg(feature = "json")]
        V::Json(value) | V::JsonOpt(Some(value)) => literal(&value.to_string()),
        V::Other { text, .. } => literal(text),
        _ => "NULL".to_string(),
    }
}

/// A column's definition: name, type, identity, default, nullability.
fn column_sql(
    name: &str,
    data_type: &DataType,
    nullable: bool,
    identity: bool,
    default: Option<&DatabaseValue>,
) -> Result<String, DatabaseError> {
    let mut sql = format!("{} {}", identifier(name), type_sql(data_type)?);
    if identity || matches!(data_type, DataType::Serial | DataType::BigSerial) {
        sql.push_str(" GENERATED BY DEFAULT ON NULL AS IDENTITY");
    } else if let Some(default) = default {
        write!(sql, " DEFAULT {}", default_sql(default)).ok();
    }
    sql.push_str(if nullable { " NULL" } else { " NOT NULL" });
    Ok(sql)
}

/// `CREATE TABLE` for `statement` (in a block that ignores an existing
/// table for `if_not_exists`).
///
/// # Errors
///
/// * [`DatabaseError::InvalidSchema`] for a table without columns or a
///   constraint that can't be rendered
/// * [`DatabaseError::UnsupportedDataType`] for array columns
pub(super) fn create_table_sql(
    statement: &crate::schema::CreateTableStatement<'_>,
) -> Result<String, DatabaseError> {
    if statement.columns.is_empty() {
        return Err(DatabaseError::InvalidSchema(format!(
            "table '{}' has no columns",
            statement.table_name
        )));
    }
    let mut parts = statement
        .columns
        .iter()
        .map(|column| {
            column_sql(
                &column.name,
                &column.data_type,
                column.nullable,
                column.auto_increment,
                column.default.as_ref(),
            )
        })
        .collect::<Result<Vec<_>, _>>()?;
    if let Some(primary_key) = statement.primary_key {
        parts.push(format!("PRIMARY KEY ({})", identifier(primary_key)));
    }
    for constraint in &statement.constraints {
        parts.push(constraint.render('"')?);
    }
    for (source, target) in &statement.foreign_keys {
        parts.push(format!(
            "FOREIGN KEY ({}) REFERENCES {}",
            identifier(source),
            identifier(target)
        ));
    }
    let create = format!(
        "CREATE TABLE {} ({})",
        identifier(statement.table_name),
        parts.join(", ")
    );
    Ok(if statement.if_not_exists {
        ignoring(&create, ALREADY_EXISTS)
    } else {
        create
    })
}

/// Run `CREATE TABLE`.
pub(super) async fn create_table(
    executor: &dyn Executor,
    statement: &crate::schema::CreateTableStatement<'_>,
) -> Result<(), DatabaseError> {
    executor
        .run_sql(&create_table_sql(statement)?, &[])
        .await
        .map(|_| ())
}

/// The first column of each row, as text.
#[cfg(feature = "cascade")]
fn names(rows: Vec<Vec<DatabaseValue>>) -> Vec<String> {
    rows.into_iter()
        .filter_map(|row| match row.into_iter().next() {
            Some(DatabaseValue::String(name)) => Some(name),
            _ => None,
        })
        .collect()
}

/// Tables (`OWNER.TABLE`) with a foreign key referencing `table` in the
/// current schema (one level).
///
/// # Errors
///
/// * If the catalog query fails
#[cfg(feature = "cascade")]
pub(super) async fn direct_dependents(
    executor: &dyn Executor,
    table: &str,
) -> Result<std::collections::BTreeSet<String>, DatabaseError> {
    let (owner, name) = table.split_once('.').map_or_else(
        || (None, table.to_string()),
        |(owner, name)| (Some(owner.to_string()), name.to_string()),
    );
    let result = executor
        .run_sql(
            "SELECT DISTINCT c.owner || '.' || c.table_name FROM all_constraints c \
             JOIN all_constraints r ON r.owner = c.r_owner \
             AND r.constraint_name = c.r_constraint_name \
             WHERE c.constraint_type = 'R' AND r.table_name = :1 \
             AND r.owner = COALESCE(:2, SYS_CONTEXT('USERENV', 'CURRENT_SCHEMA')) \
             AND NOT (c.owner = r.owner AND c.table_name = r.table_name)",
            &[
                DatabaseValue::String(name),
                owner.map_or(DatabaseValue::Null, DatabaseValue::String),
            ],
        )
        .await?;
    Ok(names(result.rows).into_iter().collect())
}

/// `table` and every table depending on it, dependents first.
///
/// # Errors
///
/// * If a catalog query fails
#[cfg(feature = "cascade")]
pub(super) async fn drop_order(
    executor: &dyn Executor,
    table: &str,
) -> Result<Vec<String>, DatabaseError> {
    // Depth-first, so each table comes after everything that references it.
    let mut order = Vec::new();
    let mut seen = std::collections::BTreeSet::new();
    let mut stack = vec![(table.to_string(), false)];
    while let Some((name, expanded)) = stack.pop() {
        if expanded {
            order.push(name);
            continue;
        }
        if !seen.insert(name.clone()) {
            continue;
        }
        stack.push((name.clone(), true));
        for dependent in direct_dependents(executor, &name).await? {
            if !seen.contains(&dependent) {
                stack.push((dependent, false));
            }
        }
    }
    Ok(order)
}

/// Run `DROP TABLE`, dropping dependents first for `CASCADE` and refusing
/// for `RESTRICT` when other tables depend on it.
///
/// # Errors
///
/// * [`DatabaseError::InvalidQuery`] for `RESTRICT` with dependents
/// * If a statement fails
pub(super) async fn drop_table(
    executor: &dyn Executor,
    statement: &crate::schema::DropTableStatement<'_>,
) -> Result<(), DatabaseError> {
    let drop = |target: String| {
        let sql = format!("DROP TABLE {target}");
        if statement.if_exists {
            ignoring(&sql, NO_SUCH_TABLE)
        } else {
            sql
        }
    };
    #[cfg(feature = "cascade")]
    {
        use crate::schema::DropBehavior;
        match statement.behavior {
            DropBehavior::Cascade => {
                for table in drop_order(executor, statement.table_name).await? {
                    // Catalog names are `OWNER.TABLE`; the first is as given.
                    let target = if table == statement.table_name {
                        identifier(&table)
                    } else {
                        table.split_once('.').map_or_else(
                            || identifier(&table),
                            |(owner, name)| format!("{}.{}", quoted(owner), quoted(name)),
                        )
                    };
                    executor.run_sql(&drop(target), &[]).await?;
                }
                return Ok(());
            }
            DropBehavior::Restrict => {
                if !direct_dependents(executor, statement.table_name)
                    .await?
                    .is_empty()
                {
                    return Err(DatabaseError::InvalidQuery(format!(
                        "Cannot drop table '{}' because other tables depend on it",
                        statement.table_name
                    )));
                }
            }
            DropBehavior::Default => {}
        }
    }
    executor
        .run_sql(&drop(identifier(statement.table_name)), &[])
        .await?;
    Ok(())
}

/// `CREATE INDEX` for `statement`.
///
/// # Errors
///
/// * [`DatabaseError::InvalidSchema`] for an index without columns
/// * [`DatabaseError::UnsupportedOperation`] for a partial index (Oracle
///   has none)
pub(super) fn create_index_sql(
    statement: &crate::schema::CreateIndexStatement<'_>,
) -> Result<String, DatabaseError> {
    if statement.predicate.is_some() {
        return Err(DatabaseError::UnsupportedOperation(
            "partial indexes on Oracle".to_string(),
        ));
    }
    let mut columns = statement
        .columns
        .iter()
        .map(|column| identifier(column))
        .collect::<Vec<_>>();
    columns.extend(statement.ordered_columns.iter().map(|(column, direction)| {
        format!(
            "{} {}",
            identifier(column),
            match direction {
                crate::query::SortDirection::Asc => "ASC",
                crate::query::SortDirection::Desc => "DESC",
            }
        )
    }));
    if columns.is_empty() {
        return Err(DatabaseError::InvalidSchema(format!(
            "index '{}' has no columns",
            statement.index_name
        )));
    }
    let sql = format!(
        "CREATE {}INDEX {} ON {} ({})",
        if statement.unique { "UNIQUE " } else { "" },
        identifier(statement.index_name),
        identifier(statement.table_name),
        columns.join(", ")
    );
    Ok(if statement.if_not_exists {
        ignoring(&sql, ALREADY_EXISTS)
    } else {
        sql
    })
}

/// Run `CREATE INDEX`.
pub(super) async fn create_index(
    executor: &dyn Executor,
    statement: &crate::schema::CreateIndexStatement<'_>,
) -> Result<(), DatabaseError> {
    executor
        .run_sql(&create_index_sql(statement)?, &[])
        .await
        .map(|_| ())
}

/// `DROP INDEX name` for `statement` (Oracle index names are unique in a
/// schema, so the table isn't named).
#[must_use]
pub(super) fn drop_index_sql(statement: &crate::schema::DropIndexStatement<'_>) -> String {
    let sql = format!("DROP INDEX {}", identifier(statement.index_name));
    if statement.if_exists {
        ignoring(&sql, NO_SUCH_INDEX)
    } else {
        sql
    }
}

/// Run `DROP INDEX`.
pub(super) async fn drop_index(
    executor: &dyn Executor,
    statement: &crate::schema::DropIndexStatement<'_>,
) -> Result<(), DatabaseError> {
    executor
        .run_sql(&drop_index_sql(statement), &[])
        .await
        .map(|_| ())
}

/// Whether `table`.`column` (in the current schema) allows nulls now.
async fn is_nullable(
    executor: &dyn Executor,
    table: &str,
    column: &str,
) -> Result<bool, DatabaseError> {
    let result = executor
        .run_sql(
            "SELECT nullable FROM all_tab_columns WHERE owner = \
             SYS_CONTEXT('USERENV', 'CURRENT_SCHEMA') AND table_name = :1 AND column_name = :2",
            &[
                DatabaseValue::String(table.to_string()),
                DatabaseValue::String(column.to_string()),
            ],
        )
        .await?;
    match result.rows.first().and_then(|row| row.first()) {
        Some(DatabaseValue::String(value)) => Ok(value == "Y"),
        _ => Err(DatabaseError::InvalidSchema(format!(
            "column '{column}' of '{table}' doesn't exist"
        ))),
    }
}

/// Run `ALTER TABLE`, one statement per operation.
///
/// # Errors
///
/// * [`DatabaseError::UnsupportedDataType`] for array columns
/// * [`DatabaseError::InvalidSchema`] if a `CHECK` can't be rendered or a
///   modified column doesn't exist
/// * If a statement fails
pub(super) async fn alter_table(
    executor: &dyn Executor,
    statement: &crate::schema::AlterTableStatement<'_>,
) -> Result<(), DatabaseError> {
    let table = identifier(statement.table_name);
    for operation in &statement.operations {
        let sql = match operation {
            AlterOperation::AddColumn {
                name,
                data_type,
                nullable,
                default,
            } => {
                let mut column = column_sql(name, data_type, *nullable, false, default.as_ref())?;
                if let Some(check) = statement.column_checks.get(name) {
                    write!(column, " CHECK ({})", check.render('"')?).ok();
                }
                format!("ALTER TABLE {table} ADD ({column})")
            }
            AlterOperation::DropColumn { name, .. } => {
                format!("ALTER TABLE {table} DROP COLUMN {}", identifier(name))
            }
            AlterOperation::RenameColumn { old_name, new_name } => format!(
                "ALTER TABLE {table} RENAME COLUMN {} TO {}",
                identifier(old_name),
                identifier(new_name)
            ),
            AlterOperation::ModifyColumn {
                name,
                new_data_type,
                new_nullable,
                new_default,
            } => {
                let mut column = format!("{} {}", identifier(name), type_sql(new_data_type)?);
                if let Some(default) = new_default {
                    write!(column, " DEFAULT {}", default_sql(default)).ok();
                }
                // Oracle refuses to "change" nullability to what it is.
                if let Some(nullable) = new_nullable
                    && *nullable != is_nullable(executor, statement.table_name, name).await?
                {
                    column.push_str(if *nullable { " NULL" } else { " NOT NULL" });
                }
                format!("ALTER TABLE {table} MODIFY ({column})")
            }
        };
        executor.run_sql(&sql, &[]).await?;
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::schema::Column;

    #[test]
    fn create_table_uses_identity_and_char_lengths() {
        let statement = crate::schema::create_table("albums")
            .if_not_exists(true)
            .column(Column {
                name: "id".to_string(),
                nullable: false,
                auto_increment: true,
                data_type: DataType::BigInt,
                default: None,
            })
            .column(Column {
                name: "title".to_string(),
                nullable: true,
                auto_increment: false,
                data_type: DataType::VarChar(200),
                default: Some(DatabaseValue::String("it's".to_string())),
            })
            .column(Column {
                name: "added".to_string(),
                nullable: false,
                auto_increment: false,
                data_type: DataType::DateTime,
                default: Some(DatabaseValue::Now),
            })
            .primary_key("id");
        let sql = create_table_sql(&statement).unwrap();
        assert!(
            sql.starts_with("BEGIN EXECUTE IMMEDIATE 'CREATE TABLE "),
            "{sql}"
        );
        assert!(sql.contains("SQLCODE <> -955"), "{sql}");
        assert!(
            sql.contains("NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL"),
            "{sql}"
        );
        assert!(
            sql.contains("VARCHAR2(200 CHAR) DEFAULT ''it''''s'' NULL"),
            "{sql}"
        );
        assert!(
            sql.contains("TIMESTAMP DEFAULT SYS_EXTRACT_UTC(SYSTIMESTAMP) NOT NULL"),
            "{sql}"
        );
    }

    #[test]
    fn arrays_and_partial_indexes_are_refused() {
        assert!(matches!(
            type_sql(&DataType::Array(Box::new(DataType::Int))),
            Err(DatabaseError::UnsupportedDataType(_))
        ));
        let statement = crate::schema::create_index("albums_title")
            .table("albums")
            .column("title")
            .if_not_exists(true);
        let sql = create_index_sql(&statement).unwrap();
        assert!(sql.contains("SQLCODE <> -955"), "{sql}");
    }
}
